ST.xhtml:p:
R_Trigger1(CLK := g_biLoadZeroOpen);
R_Trigger2(CLK := g_biLoadZeroClose);
R_Trigger3(CLK := bLoadHome);

IF R_Trigger1.Q THEN
  nLoadState := 1;
  g_boLoadZeroDone := FALSE;
END_IF;
IF R_Trigger2.Q THEN
  g_boLoadZeroDone := FALSE;
END_IF;
IF R_Trigger3.Q THEN
  nLoadState := 3;
END_IF;

CASE nLoadState OF
  0:
    nLoadState := 0;
  1:
    g_LoadAbs.Execute := TRUE;
    g_LoadAbs.Velocity := dLoadZeroVel;
    g_LoadAbs.Position := 0.0;
    IF g_LoadAbs.Done THEN
      g_LoadAbs.Execute := FALSE;
      g_boLoadZeroDone := TRUE;
      nLoadState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nLoadState := 20;
    END_IF;
    IF g_LoadAbs.CommandAborted OR g_LoadAbs.Error THEN
      g_LoadAbs.Execute := FALSE;
      g_boLoadZeroDone := FALSE;
      nLoadState := 0;
    END_IF;
  3:
    g_LoadHome.Execute := TRUE;
    g_LoadHome.HomingMode := 5;
    IF g_LoadHome.Done THEN
      g_LoadHome.Execute := FALSE;
      nLoadState := 0;
    END_IF;
  20:
    g_LoadAbs.Execute := FALSE;
    g_LoadStop.Execute := TRUE;
    IF g_LoadStop.Done AND g_bPlcStartBuffer THEN
      g_LoadStop.Execute := FALSE;
      nLoadState := 1;
    END_IF;
    IF g_LoadStop.CommandAborted OR g_LoadStop.Error THEN
      g_LoadStop.Execute := FALSE;
      nLoadState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nLoadState := 0;
  g_LoadAbs.Execute := FALSE;
  g_LoadStop.Execute := FALSE;
  g_LoadHome.Execute := FALSE;
END_IF;
